#!/usr/bin/env python3
import requests

def check_endpoint(url, name):
    try:
        response = requests.get(url, timeout=10)
        if response.status_code == 200:
            print(f"{name}: SUCCESS - HTTP {response.status_code} - {response.text.strip()}")
        else:
            print(f"{name}: FAILED - HTTP {response.status_code}")
    except requests.exceptions.RequestException as e:
        print(f"{name}: ERROR - {e}")

def main():
    # Check first endpoint
    check_endpoint("http://localhost:3003/checkConnectivity?variant=1", "Local Service")

    # Check second endpoint
    check_endpoint("https://httpstat.us/200", "HTTPStat")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import requests

def check_endpoint(url, name):
    try:
        response = requests.get(url, timeout=10)
        print(f"{name}:")
        print(f"  URL: {url}")
        print(f"  Status Code: {response.status_code}")
        print(f"  Response: {response.text.strip() if response.text else 'No content'}")
    except Exception as e:
        print(f"{name}:")
        print(f"  URL: {url}")
        print(f"  Error: {str(e)}")

if __name__ == "__main__":
    check_endpoint("http://localhost:3003/checkConnectivity?variant=1", "Local Service")
    check_endpoint("https://httpstat.us/200", "HTTPStat")

